INSERT INTO `destinos` VALUES (1,1,'ICA','Desierto','4.6','https://tse4.mm.bing.net/th/id/OIP.6Sjeb600zZY3NCEggs_MegHaEr?r=0&cb=thfc1falcon4&rs=1&pid=ImgDetMain&o=7&rm=3',5,NULL),(2,1,'LIMA','Gastronomía','4.5','https://imgmedia.larepublica.pe/1000x590/larepublica/original/2025/07/09/686ee9f7b0ed096954049430.webp',9,NULL),(3,1,'TRUJILLO','Historia','4.6','https://thf.bing.com/th/id/R.190a61be9c8a3fc52aa4dc9c9ed5bbca?rik=GFghdCH4UrLMXA&riu=http%3a%2f%2fblog.redbus.pe%2fwp-content%2fuploads%2f2018%2f03%2fCathedral_of_Trujillo_Peru_02.jpg&ehk=1Qe5U68RLuyyv34ShhR1ssD4IPQLy7SKLJ2HQON9g4Q%3d&risl=&pid=ImgRaw&r=0',6,NULL),(4,2,'AREQUIPA','Colonial','4.7','https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQdP_gAhENVm6c1lES-uV3sy-Wp2BAs6tnxiQm8IzN-gQ&s=10',7,NULL),(5,2,'AYACUCHO','Cultura','4.5','https://blog.redbus.pe/wp-content/uploads/2021/06/shutterstock_448948582-scaled-e1623365783166-2048x1059.jpg',4,NULL),(6,2,'CAJAMARCA','Historia','4.6','https://static.wixstatic.com/media/545a5a_da62c27bb29a40fb971d08b23c9bf01a~mv2.jpg/v1/fill/w_1000,h_680,al_c,q_85,usm_0.66_1.00_0.01/545a5a_da62c27bb29a40fb971d08b23c9bf01a~mv2.jpg',5,NULL),(7,2,'CHACHAPOYAS','Aventura','4.7','https://miviaje.com/wp-content/uploads/2019/12/kuelap-1.jpg',3,NULL),(8,2,'CUSCO','Historia','4.9','https://tse1.mm.bing.net/th/id/OIP.RTawFktGQ_u6H8oZRRZr0gHaFj?r=0&cb=thfc1falcon4&rs=1&pid=ImgDetMain&o=7&rm=3',12,NULL),(9,2,'PUNO','Cultura','4.7','https://thumbs.dreamstime.com/b/floating-tourist-islands-lake-titicaca-puno-peru-floating-tourist-islands-lake-titicaca-puno-peru-south-373164071.jpg?w=992',6,NULL),(10,3,'IQUITOS','Amazonía','4.8','https://tse1.mm.bing.net/th/id/OIP.yWanjcYa0BJzS9Fv7PYmNgHaEH?r=0&cb=thfc1falcon4&rs=1&pid=ImgDetMain&o=7&rm=3',8,NULL),(11,3,'LORETO','Naturaleza','4.7','https://www.travelreport.mx/wp-content/uploads/2024/07/peru-amazonia-loreto-3.jpg',6,NULL),(12,3,'MADRE DE DIOS','Fauna','4.8','https://tse4.mm.bing.net/th/id/OIP.iFUQRSPF1O0PUsUeN8IxYQHaDo?r=0&cb=thfc1falcon4&rs=1&pid=ImgDetMain&o=7&rm=3',5,NULL),(13,3,'PUERTO MALDONADO','Ecoturismo','4.6','https://www.turiweb.pe/wp-content/uploads/2024/12/puerto-maldonado-261224.jpg',7,NULL),(14,3,'TINGO MARIA','Aventura','4.5','https://thf.bing.com/th/id/R.652e45e5ced6ffe8a7570dff89c40f3e?rik=GO6LjB3LSHav2Q&pid=ImgRaw&r=0',4,NULL),(15,2,'Cusco','Historia y cultura','4.9','https://www.postposmo.com/wp-content/uploads/2020/09/CUZCO-19.jpg',8,'Ciudad imperial con ruinas incas, mercados y gastronomía andina.'),(16,2,'Machu Picchu','Maravilla ancestral','5.0','https://tse4.mm.bing.net/th/id/OIP._MVYt6uqnNMmrymzS-s4EwHaFj?r=0&cb=thfc1falcon4&rs=1&pid=ImgDetMain&o=7&rm=3',12,'La ciudad perdida de los incas, un destino imperdible para viajeros.'),(17,1,'Lima','Costa moderna','4.5','https://tse4.mm.bing.net/th/id/OIP.zUds4uukMyum-a43s4Y4cAHaE-?r=0&cb=thfc1falcon4&rs=1&pid=ImgDetMain&o=7&rm=3',5,'Capital con playas, gastronomía premium y vida nocturna vibrante.'),(18,3,'Iquitos','Aventura selvática','4.7','https://perujungletrips.com/wp-content/uploads/2025/02/Lago-Sandoval-5.jpg',4,'Puerta de entrada a la Amazonía peruana y sus experiencias únicas.');
