INSERT INTO `itinerario` VALUES (1,1,1,'Llegada a Cusco','Recepción en el aeropuerto, traslado al hotel y aclimatación. City tour opcional por la tarde.'),(2,1,2,'Valle Sagrado','Excursión al Valle Sagrado: Pisac, Ollantaytambo y mercados artesanales.'),(3,1,3,'Machu Picchu','Tren panorámico hacia Aguas Calientes. Tour completo por la ciudadela de Machu Picchu con guía experto.'),(4,1,4,'Cusco Imperial','Visita al Qoricancha, Plaza de Armas, Sacsayhuamán y mercado de San Pedro.'),(5,1,5,'Regreso','Check-out, traslado al aeropuerto y vuelo de regreso a Lima.'),(6,2,1,'Llegada a Puerto Maldonado','Traslado al lodge. Charla de bienvenida y exploración inicial.'),(7,2,2,'Lago Sandoval','Navegación por el lago Sandoval, avistamiento de caimanes y nutrias gigantes.'),(8,2,3,'Canopy & Zip Line','Recorrido por el dosel arbóreo, observación de aves desde plataformas.'),(9,2,4,'Comunidades nativas','Visita a comunidades indígenas, aprendizaje de técnicas ancestrales.'),(10,2,5,'Río Madre de Dios','Expedición en lancha, pesca de pirañas, baño en el río.'),(11,2,6,'Caminata nocturna','Observación de la vida nocturna de la selva con guía experto.'),(12,2,7,'Regreso','Traslado al aeropuerto y vuelo de regreso a Lima.'),(13,3,1,'City Tour Ica + Huacachina','Recepción y traslado al hotel. Visita a bodega vitivinícola artesanal con degustación de vinos y piscos. Experiencia en la Casa de las Tejas Rosalía. Recorrido por la Plaza de Armas y visita a la Laguna de Huacachina, \"Oasis de América\". (No incluye buggies ni sandboarding)'),(14,3,2,'Islas Ballestas + Reserva Nacional de Paracas','Traslado al muelle turístico en Paracas. Paseo en deslizador hacia las Islas Ballestas para observar aves, lobos marinos y pingüinos de Humboldt. Retorno y visita a la Reserva Nacional de Paracas: mirador de La Catedral, Playa Supay, Playa Roja y Centro de Interpretación. Tiempo libre en Playa Lagunillas. Retorno a Ica.'),(15,3,3,'Salida de Ica','Desayuno en el hotel. Tiempo libre y traslado a la estación de bus para retorno a Lima.'),(16,4,1,'Llegada a Puno','Traslado, visita al mercado y paseo por la bahía del Titicaca.'),(17,4,2,'Islas Uros','Bote de totora a las islas flotantes de los Uros, artesanías y danza.'),(18,4,3,'Taquile & Amantaní','Estadía con familia local en isla Amantaní, astronomía nocturna.'),(19,4,4,'Regreso','Retorno a Puno, traslado a Cusco o aeropuerto.'),(20,5,1,'Circuito Mágico del Agua + Cena Show','Recepción en aeropuerto Jorge Chávez y traslado a hotel en Miraflores. Por la noche, visita al Parque de la Reserva con espectáculo de fuentes de agua, luces y música. Cena en restaurante con show folclórico.'),(21,5,2,'City Tour + Museo Larco + Cena en Huaca Pucllana','Recorrido por el Centro Histórico: Plaza San Martín, Plaza Mayor, Palacio de Gobierno, Catedral y catacumbas de San Francisco. Visita al Museo Larco y contraste con la Lima moderna (San Isidro, Miraflores, Parque del Amor). Cena en la Huaca Pucllana.'),(22,5,3,'Pachacamac + Caballos de Paso + Almuerzo Buffet','Visita panorámica a la pirámide de Pucllana y traslado al Oráculo de Pachacamac. Recorrido por el Templo del Sol, Templo de Pachacamac y Acllahuasi. Retorno a la hacienda D\'Paso en Mamacona: exhibición de Caballos Peruanos de Paso, show de marinera y almuerzo buffet.'),(23,5,4,'Salida de Lima','Traslado al aeropuerto Jorge Chávez según horario de vuelo.'),(24,6,1,'Arequipa','Llegada a Arequipa, visita al Monasterio de Santa Catalina y mirador.'),(25,6,2,'Cañón del Colca','Viaje a Chivay por el altiplano. Baños termales por la tarde.'),(26,6,3,'Vuelo del Cóndor','Amanecer en el mirador Cruz del Cóndor. Avistamiento de cóndores.'),(27,6,4,'Regreso','Retorno a Arequipa, visita al mercado San Camilo y aeropuerto.'),(28,7,1,'Centro Histórico y Pasado Colonial','Recorrido por Plaza San Martín y Plaza Mayor, Palacio de Gobierno y Palacio Municipal. Ingreso a la Catedral y visita a la urna de Francisco Pizarro. Caminata hacia la Iglesia y Convento de San Francisco con experiencia en las catacumbas.'),(29,7,2,'Secretos Coloniales y Catacumbas','Profundización en el legado colonial con guía especializada en la Catedral y San Francisco. Experiencia inmersiva en las catacumbas.'),(30,7,3,'Lima Moderna y Vistas al Pacífico','Recorrido por San Isidro y Miraflores. Paseo por el circuito de playas y visita al Parque del Amor. Posibilidad de vuelo en parapente (actividad opcional con costo adicional).'),(31,7,4,'Tiempo libre y salida','Actividades personales y traslado según itinerario de viaje.'),(32,8,1,'Lima – Trujillo / Chan-Chan y Huanchaco','Recepción y traslado al hotel. Visita a las ruinas de Chan-Chan, ciudad de barro más grande del mundo y Patrimonio Cultural de la Humanidad. Almuerzo en Huanchaco, balneario famoso por los \"Caballitos de Totora\".'),(33,8,2,'Pirámides del Sol y la Luna','Excursión al Valle de Moche para conocer las pirámides de adobe, con relieves policromados descubiertos en recientes excavaciones.'),(34,8,3,'Trujillo – Chiclayo','Traslado en bus regular (3 horas). Recepción en Chiclayo y tarde libre para recorrer la ciudad.'),(35,8,4,'Chiclayo – Túcume y Museo Tumbas Reales','Visita al Complejo Arqueológico de Túcume (Valle de las Pirámides). Retorno y visita al Museo Tumbas Reales de Sipán, considerado uno de los más modernos de Sudamérica. Traslado al aeropuerto para retorno a Lima.'),(36,9,1,'Trujillo – City Tour a pie','Recepción y traslado al hotel. Recorrido por Plaza Mayor, Casa de la Identidad, Casa Urquiaga, Jirón Pizarro, Casa de la Emancipación y Palacio Iturregui. Visita al Museo de Arqueología de la UNT.'),(37,9,2,'Huacas del Sol y la Luna – Chan Chan – Huanchaco','Excursión a las Huacas del Sol y la Luna con murales policromos. Almuerzo libre en Trujillo. Visita al Palacio Nikan (Chan Chan) y paseo por la playa de Huanchaco.'),(38,9,3,'Chiclayo – Sipán y Museos','Viaje en bus hacia Chiclayo. Visita a Huaca Rajada (tumba del Señor de Sipán), Museo Tumbas Reales y Museo Bruning en Lambayeque. Retorno y alojamiento en Trujillo.'),(39,9,4,'Trujillo Out','Desayuno y día libre. Opcional: exhibición de Caballos de Paso + Marinera o visita a El Brujo y Museo de Cao. Traslado al aeropuerto.'),(40,10,1,'Arequipa – Chivay','Recepción en aeropuerto y traslado. Viaje hacia el Valle del Colca con paradas en miradores naturales y pueblos típicos. Llegada a Chivay, almuerzo libre y tarde de descanso. Cena opcional con show folclórico.'),(41,10,2,'Colca – Cruz del Cóndor – Arequipa','Muy temprano salida hacia el mirador de Cruz del Cóndor para observar el vuelo de los cóndores. Recorrido por pueblos tradicionales (Yanque, Maca). Retorno a Arequipa con paradas en miradores y paisajes altoandinos. Traslado al aeropuerto o estación de bus.'),(42,11,1,'Arequipa – City Tour','Recepción en aeropuerto y traslado al hotel. Recorrido por el centro histórico, Monasterio de Santa Catalina y miradores de Yanahuara y Carmen Alto.'),(43,11,2,'Valle del Colca – Chivay','Salida hacia el Valle del Colca con paradas en miradores naturales y pueblos típicos. Llegada a Chivay, almuerzo libre y tarde de descanso. Cena opcional con show folclórico.'),(44,11,3,'Cruz del Cóndor – Retorno a Arequipa','Muy temprano visita al mirador de Cruz del Cóndor para observar el vuelo de los cóndores. Recorrido por pueblos como Yanque y Maca. Retorno a Arequipa y traslado al aeropuerto o estación de bus.'),(45,12,1,'City Tour + Monasterio de Santa Catalina','Recepción en aeropuerto y traslado al hotel. Por la tarde, recorrido por el centro histórico y visita al Monasterio de Santa Catalina, considerado una ciudadela única con más de cuatro siglos de historia.'),(46,12,2,'Campiña Arequipeña + Molino de Sabandía','Excursión a la campiña: Tingo, Mirador de Sachaca, Casa del Fundador, Paucarpata con andenería preinca y el tradicional Molino de Sabandía. Resto del día libre.'),(47,12,3,'Salida de Arequipa','Desayuno en el hotel. Traslado al aeropuerto para retorno a Lima.'),(48,13,1,'Tour Campiña Arequipeña','Recepción y traslado al hotel. Excursión a Paucarpata con andenería preinca, Molino de Sabandía, Mansión del Fundador, lagos artificiales de Tingo y Mirador de Sachaca. Almuerzo opcional en la campiña. Retorno y alojamiento en Arequipa.'),(49,13,2,'Tour del Sillar','Desayuno en el hotel. Visita a la Plaza e Iglesia de Cayma, luego a la Cantera de Añashuayco para observar la extracción y tallado del sillar. Caminata por la Quebrada de Culebrillas para ver petroglifos de la cultura Wari y apachetas. Retorno y tarde libre.'),(50,13,3,'Arequipa Out','Desayuno en el hotel. Tiempo libre y traslado a la estación/aeropuerto para retorno a ciudad de origen.'),(51,14,1,'Arequipa – City Tour + Santa Catalina','Recepción y traslado al hotel. Por la tarde, recorrido histórico y visita al Monasterio de Santa Catalina, ciudadela colonial única en el mundo.'),(52,14,2,'Arequipa – Chivay (Cañón del Colca)','Excursión al Cañón del Colca con paradas en Pampa Cañahuas, Mirador de los Andes, Cráter de Chucura y Mirador de Chivay. Alojamiento en Chivay.'),(53,14,3,'Colca – Cruz del Cóndor – Puno','Visita al mirador Cruz del Cóndor para observar el vuelo de los cóndores. Recorrido por tumbas colgantes, Pueblo de Yanque y Mirador de Chilina. Traslado en bus turístico hacia Puno (6 horas).'),(54,14,4,'Puno – Islas Uros y Taquile','Excursión a las Islas Flotantes de los Uros para conocer sus costumbres y construcción en totora. Continuación hacia la Isla Taquile con almuerzo incluido. Retorno a Puno.'),(55,14,5,'Puno – Sillustani – Lima','Visita al cementerio preinca de Sillustani, junto al lago Umayo. Traslado al aeropuerto de Juliaca para retorno a Lima.'),(56,15,1,'City Tour Ayacucho','Recepción y traslado al hotel. Por la tarde, recorrido por Plaza Mayor, Casona Bosa y Solís, Templo y Convento de Santa Teresa, Mirador de Acuchimay y Barrio Artesanal de Santa Ana, famoso por la piedra de Huamanga y la textilería.'),(57,15,2,'Piscina Natural de Millpu','Excursión a las aguas turquesas de Millpu, con caminata de 2 horas para apreciar las pozas desde lo alto y llegar al \"ojo de agua\". Durante el trayecto se observa flora, fauna y paisajes naturales únicos.'),(58,15,3,'Ayacucho Out','Desayuno en el hotel. Día libre para actividades personales. Traslado a estación o aeropuerto según itinerario.'),(59,16,1,'City Tour Histórico','Recepción en aeropuerto y traslado al hotel. Por la tarde, visita a la casona Boza y Solís, templos Santo Domingo y Santa Teresa, Alameda Valdelirios y Mirador de Acuchimay. Experiencia con artesanos locales: elaboración de retablos ayacuchanos, tallado en piedra de Huamanga y tablas de Sarhua.'),(60,16,2,'Ruta de la Independencia – Pampa de Ayacucho','Excursión al complejo arqueológico de Wari: museo de sitio, templo mayor y mausoleos. Visita al pueblo de Quinua, famoso por su cerámica artesanal. Recorrido por la Pampa de Ayacucho, escenario histórico de la batalla que selló la independencia del Perú.'),(61,16,3,'Ayacucho Out','Desayuno en el hotel. Mañana libre para actividades personales. Traslado al aeropuerto o terrapuerto según itinerario.'),(62,17,1,'City Tour Histórico','Recepción y traslado al hotel. Por la tarde, recorrido por Plaza Mayor, templos coloniales, miradores y barrios artesanales como Santa Ana.'),(63,17,2,'Millpu – Piscinas Naturales','Excursión a las famosas aguas turquesas de Millpu. Caminata de 2 horas para apreciar las pozas, cascadas y el \"ojo de agua\". Observación de flora y fauna local.'),(64,17,3,'Ecoaventura en los alrededores de Ayacucho','Caminata por paisajes naturales, visita a miradores y pueblos tradicionales. Actividades de contacto con la naturaleza y cultura local.'),(65,17,4,'Ayacucho Out','Desayuno en el hotel. Tiempo libre para actividades personales. Traslado a estación o aeropuerto.'),(66,18,1,'City Tour Cajamarca','Recepción y traslado al hotel. Por la tarde, recorrido por Catedral, Plaza de Armas, San Francisco, Complejo Belén, Cuarto del Rescate y Mirador de Santa Apolonia.'),(67,18,2,'Otuzco – Baños del Inca – La Collpa','Excursión a la necrópolis de Otuzco, hacienda Tres Molinos y Fundo Los Alpes con caballos de paso y degustación de productos lácteos. Almuerzo típico. Visita a la ex hacienda La Collpa, distrito de Llacanora y baños termales del Inca.'),(68,18,3,'Cumbemayo – Retorno','Excursión a Cumbemayo: Bosque de Piedras, Santuario, Acueducto y Piedra de Sacrificio. Por la tarde, traslado al aeropuerto o estación de bus.'),(69,19,1,'Ingreso del Ño Carnavalón + Otuzco','Recepción y traslado al hotel. Participación en la entrada del Ño Carnavalón con música, comparsas y coplas carnavalescas. Excursión a las Ventanillas de Otuzco, jardín de hortensias y Fundo Los Alpes. Por la noche, participación en bailes y cantos en la Plaza de Armas.'),(70,19,2,'Desfile de Patrullas + Hacienda La Collpa','Participación en el concurso de patrullas y comparsas por las calles de Cajamarca. Por la tarde, visita a la ex hacienda La Collpa con su tradicional llamado de vacas por nombre, y excursión a Llacanora para ver las cascadas de agua hembra y macho.'),(71,19,3,'Corso Carnavalesco','Gran desfile con patrullas, comparsas, carros alegóricos y reinas del carnaval. Tarde libre para compras.'),(72,19,4,'Granja Porcón – Fin de servicios','Excursión a Huambocancha para apreciar tallados en piedra y visita a la Granja Porcón, con bosque de pinos y minizoológico. Traslado a estación o aeropuerto.'),(73,20,1,'City Tour Cajamarca','Recepción y traslado al hotel. Recorrido por Catedral, Plaza de Armas, San Francisco, Complejo Belén, Cuarto del Rescate y Colina de Santa Apolonia.'),(74,20,2,'Otuzco – Baños del Inca – La Collpa','Excursión a la necrópolis de Otuzco, Hacienda Tres Molinos, Jardín de Hortensias y Fundo Los Alpes (caballos de paso y degustación de lácteos). Almuerzo típico. Visita a la ex hacienda La Collpa, distrito de Llacanora y baños termales del Inca.'),(75,20,3,'Cumbemayo','Excursión al Bosque de Piedra, Santuario, Acueducto y Piedra de Sacrificio. Retorno a la ciudad.'),(76,20,4,'Granja Porcón – Retorno','Visita a Huambocancha (tallados en piedra) y a la Granja Porcón: bosque de pinos, talleres artesanales y minizoológico con fauna de costa, sierra y selva. Traslado al aeropuerto o estación de bus.'),(77,21,1,'Lima – Jaén – Chachapoyas','Recepción en aeropuerto de Jaén y traslado en transporte turístico a Chachapoyas. Arribo e instalación en hotel. Tarde libre para descanso y aclimatación.'),(78,21,2,'Ciudadela Fortificada de Kuelap','Excursión a Kuelap con parada en el sitio arqueológico de Macro. Traslado en teleférico al complejo, visita guiada y almuerzo. Retorno a Chachapoyas.'),(79,21,3,'Catarata de Gocta','Salida hacia Cocachimba. Caminata de 2:30 horas hasta la catarata de Gocta, observando flora, fauna y, con suerte, el gallito de las rocas. Almuerzo en Cocachimba y retorno a Chachapoyas.'),(80,21,4,'Chachapoyas – Jaén – Lima','Traslado temprano en transporte turístico al aeropuerto de Jaén para vuelo de retorno.'),(81,22,1,'Lima – Jaén – Chachapoyas','Recepción en aeropuerto de Jaén y traslado en transporte turístico a Chachapoyas. Arribo e instalación en hotel. Tarde libre para descanso y aclimatación.'),(82,22,2,'Ciudadela Fortificada de Kuelap','Excursión a Kuelap con parada en el sitio arqueológico de Macro y el pueblo de Nuevo Tingo. Ascenso en teleférico, visita guiada y almuerzo. Retorno a Chachapoyas.'),(83,22,3,'Sarcófagos de Karajía y Caverna de Quiocta','Traslado al pueblo de Cruzpata y caminata de 30 minutos para visitar los sarcófagos de Karajía, únicos en el mundo. Almuerzo y visita a la caverna de Quiocta, con estalactitas y estalagmitas. Retorno a Chachapoyas.'),(84,22,4,'Catarata de Gocta','Excursión al pueblo de Cocachimba y caminata de 2:30 horas hacia la catarata de Gocta, una de las más altas del mundo. Observación de flora, fauna y posibilidad de ver el gallito de las rocas. Almuerzo y retorno a Chachapoyas.'),(85,22,5,'Chachapoyas – Jaén – Lima','Traslado temprano en transporte turístico al aeropuerto de Jaén para vuelo de retorno.'),(86,23,1,'Puno In','Recepción en aeropuerto de Juliaca y traslado al hotel. Descanso y aclimatación.'),(87,23,2,'Islas Uros & Taquile','Excursión lacustre en embarcación rápida hacia las islas flotantes de los Uros, conociendo su estilo de vida ancestral. Continuación hacia la Isla Taquile, famosa por su textilería y tradiciones. Almuerzo incluido. Retorno a Puno.'),(88,23,3,'Gran Concurso de Danzas de Trajes de Luces','Traslado al estadio y ubicación preferencial. Observación de danzas típicas como Morenada, Diablada, Wacas, Tinkus, Tobas y Sicuris. Box lunch incluido. Retorno al hotel por cuenta del pasajero.'),(89,23,4,'Puno Out','Desayuno en el hotel. Traslado al aeropuerto de Juliaca para retorno.'),(90,24,1,'Puno – Sillustani','Recepción en aeropuerto de Juliaca y traslado al hotel. Excursión a las Chullpas de Sillustani, una de las necrópolis más grandes de América, ubicada junto a la laguna Umayo.'),(91,24,2,'Islas Uros – Amantaní','Navegación hacia las islas flotantes de los Uros, construidas con totora. Continuación hacia Amantaní, donde se conocerán sus paisajes y costumbres. Cena y pernocte en casa típica de isleños, con participación en danzas locales.'),(92,24,3,'Amantaní – Taquile – Puno','Desayuno típico en Amantaní y paseo por la isla. Traslado en barco hacia Taquile, caminata hasta el pueblo, visita a su plaza y observación de tradiciones textiles. Almuerzo incluido. Retorno a Puno.'),(93,24,4,'Puno Out','Desayuno en el hotel. Traslado al aeropuerto o estación de bus.'),(94,25,1,'Cusco – Camino Inca – Aguas Calientes','Traslado a la estación de Ollanta a las 4:00 am. Tren Expeditions hasta el km 104. Caminata de 5 horas atravesando bosque semi tropical, río Vilcanota, cascadas y vistas del glaciar Verónica. Visita al complejo arqueológico de Wiñayhuayna y almuerzo tipo box lunch. Continuación hasta Inti Punku (Puerta del Sol) con vista espectacular de Machu Picchu. Descenso a Aguas Calientes y pernocte en hotel.'),(95,25,2,'Machu Picchu – Cusco','Desayuno en el hotel. Ascenso en bus para disfrutar el amanecer en Machu Picchu. Visita guiada de la ciudadela. Retorno a Aguas Calientes en bus, almuerzo buffet incluido. Por la tarde, tren Expeditions hacia Poroy y traslado al hotel en Cusco.'),(96,26,1,'Lima – Cusco – Machu Picchu – Cusco','Arribo a Cusco y traslado inmediato a Ollanta. Tren Expedition hacia Aguas Calientes. Subida en bus a Machu Picchu para visita guiada de 2 horas por la ciudadela. Retorno a Aguas Calientes y tiempo libre. Tren Vistadome hacia Poroy y traslado al hotel en Cusco.'),(97,26,2,'Cusco – Lima','Desayuno en el hotel. Traslado al aeropuerto para vuelo de retorno a Lima u otro destino.'),(98,27,1,'Cusco – Valle Sagrado – Aguas Calientes','Recepción en aeropuerto y traslado al hotel. Excursión de día completo al Valle Sagrado: visita a Calca, Lamay, mercado de Pisaq y almuerzo en Urubamba. Por la tarde, visita a la Fortaleza de Ollantaytambo. Tren turista hacia Aguas Calientes y pernocte en hotel.'),(99,27,2,'Machu Picchu – Cusco','Desayuno en el hotel. Excursión a Machu Picchu con visita guiada por las principales edificaciones. Tiempo libre para explorar. Retorno a Aguas Calientes y almuerzo buffet. Tren de regreso a Cusco y traslado al hotel.'),(100,27,3,'Cusco – Lima','Desayuno en el hotel. Traslado al aeropuerto para retorno a Lima.'),(101,28,1,'Cusco – Km 82 – Huayllabamba','Inicio de caminata (12 km, 5–6 horas). Visita a Llactapata y almuerzo. Campamento en Huayllabamba (3,000 m.s.n.m.).'),(102,28,2,'Huayllabamba – Pacaymayo','Ascenso exigente hasta Warmiwañusca (4,200 m.s.n.m., punto más alto del trekking). Caminata de 11 km (6–7 horas). Campamento en Pacaymayo (3,500 m.s.n.m.).'),(103,28,3,'Pacaymayo – Wiñay Wayna','Caminata de 16 km (7–8 horas). Visitas a Runkuracay, Sayacmarca, Phuyupatamarca e Intipata. Campamento en Wiñay Wayna (2,650 m.s.n.m.).'),(104,28,4,'Wiñay Wayna – Machu Picchu – Cusco','Caminata hacia Inti Punku (Puerta del Sol) y entrada a Machu Picchu. Tour guiado de 2 horas. Descenso a Aguas Calientes, almuerzo buffet y tren de retorno a Cusco.'),(105,29,1,'Cusco – City Tour y Ruinas Cercanas','Recepción en aeropuerto y traslado al hotel. Por la tarde, visita a Plaza de Armas, Catedral, Coricancha y ruinas cercanas.'),(106,29,2,'Valle Sagrado – Aguas Calientes','Excursión de día completo al Valle Sagrado: Calca, Lamay, mercado de Pisaq y almuerzo en Urubamba. Por la tarde, visita a la Fortaleza de Ollantaytambo. Tren hacia Aguas Calientes y pernocte. (Opcional: ascenso a Huayna Picchu, USD 50, sujeto a disponibilidad)'),(107,29,3,'Machu Picchu – Cusco','Desayuno en el hotel. Excursión a Machu Picchu con visita guiada y tiempo libre. Almuerzo buffet en Aguas Calientes. Retorno en tren a Cusco y traslado al hotel.'),(108,29,4,'Cusco libre','Día libre para actividades personales o tours opcionales.'),(109,29,5,'Cusco – Lima','Desayuno en el hotel. Traslado al aeropuerto para vuelo de retorno.'),(110,30,1,'Cusco – City Tour y Ruinas Cercanas','Recepción en aeropuerto y traslado al hotel. Por la tarde, visita a Plaza de Armas, Catedral, Coricancha y ruinas cercanas.'),(111,30,2,'Valle Sagrado – Aguas Calientes','Excursión de día completo al Valle Sagrado: Calca, Lamay, mercado de Pisaq y almuerzo en Urubamba. Por la tarde, visita a la Fortaleza de Ollantaytambo. Tren hacia Aguas Calientes y pernocte.'),(112,30,3,'Machu Picchu – Cusco','Desayuno en el hotel. Excursión guiada a Machu Picchu con tiempo libre. Almuerzo buffet en Aguas Calientes. Retorno en tren a Cusco y traslado al hotel. (Opcional: Huayna Picchu, USD 50)'),(113,30,4,'Maras y Moray','Visita a las salineras de Maras (3,300 m.s.n.m.), con vistas a la cordillera del Vilcanota y nevados como el Chikón y La Verónica. Continuación hacia Moray (3,385 m.s.n.m.), laboratorio agrícola inca con terrazas circulares y microclimas únicos.'),(114,30,5,'Cusco – Lima','Desayuno en el hotel. Traslado al aeropuerto para vuelo de retorno.'),(115,31,1,'Cusco – City Tour y Ruinas Cercanas','Recepción en aeropuerto y traslado al hotel. Por la tarde, visita a Plaza de Armas, Catedral, Coricancha y ruinas cercanas.'),(116,31,2,'Valle Sagrado – Aguas Calientes','Excursión de día completo al Valle Sagrado: Calca, Lamay, mercado de Pisaq y almuerzo en Urubamba. Por la tarde, visita a la Fortaleza de Ollantaytambo. Tren hacia Aguas Calientes y pernocte.'),(117,31,3,'Machu Picchu – Cusco','Desayuno en el hotel. Excursión guiada a Machu Picchu con tiempo libre. Almuerzo buffet en Aguas Calientes. Retorno en tren a Cusco y traslado al hotel. (Opcional: Huayna Picchu, USD 50)'),(118,31,4,'Montaña de 7 Colores (Vinicunca)','Salida a las 03:00 am hacia Pitumarca. Desayuno en Quechuyno y caminata de 3h30 hasta Vinicunca (5,200 m.s.n.m.). Observación de la montaña multicolor y el nevado Ausangate. Almuerzo en Hachipacha y retorno a Cusco al final de la tarde.'),(119,31,5,'Cusco – Lima','Desayuno en el hotel. Traslado al aeropuerto para vuelo de retorno.'),(120,32,1,'Cusco – City Tour y Ruinas Cercanas','Recepción en aeropuerto y traslado al hotel. Por la tarde, visita a Plaza de Armas, Catedral, Coricancha y ruinas cercanas.'),(121,32,2,'Machu Picchu – Cusco','Excursión en tren turista hacia Aguas Calientes. Subida en bus a Machu Picchu, visita guiada y almuerzo buffet. Retorno en tren a Cusco y traslado al hotel.'),(122,32,3,'Cusco – Puno (bus turístico)','Traslado a estación de bus. Viaje con paradas en Andahuaylillas, Raqchi, almuerzo en Sicuani, La Raya y Pucará. Arribo a Puno y traslado al hotel.'),(123,32,4,'Lago Titicaca – Uros & Taquile','Navegación hacia las islas flotantes de los Uros y visita a Taquile. Almuerzo típico incluido. Retorno a Puno.'),(124,32,5,'Puno – Sillustani – Lima','Desayuno en el hotel. Excursión a las Chullpas de Sillustani, junto a la laguna Umayo. Traslado al aeropuerto de Juliaca para vuelo de retorno.'),(125,33,1,'Cusco – City Tour y Ruinas Cercanas','Recepción en aeropuerto y traslado al hotel. Por la tarde, visita a Plaza de Armas, Catedral, Coricancha y ruinas cercanas.'),(126,33,2,'Valle Sagrado de los Incas','Excursión de día completo: Calca, Lamay, mercado de Pisaq (en domingo), almuerzo buffet en Urubamba. Por la tarde, visita a la Fortaleza de Ollantaytambo y al poblado de Chinchero. Retorno a Cusco.'),(127,33,3,'Machu Picchu – Cusco','Traslado a estación de tren. Viaje a Aguas Calientes y subida en bus a Machu Picchu. Visita guiada por las principales edificaciones. Almuerzo buffet en El Mapi. Retorno en tren a Cusco y traslado al hotel.'),(128,33,4,'Cusco libre','Día libre para actividades personales o tours opcionales.'),(129,33,5,'Cusco – Lima','Desayuno en el hotel. Traslado al aeropuerto para vuelo de retorno.'),(130,34,1,'Cusco – Mollepata – Soraypampa','Inicio del trekking con vistas al nevado Salkantay y llegada al primer campamento en Soraypampa.'),(131,34,2,'Soraypampa – Paso Salkantay – Challway','Ascenso al paso Salkantay-Umantay (4,600 m.s.n.m.), descenso hacia la ceja de selva y campamento en Challway.'),(132,34,3,'Challway – Sawayaco (La Playa)','Caminata por el río Santa Teresa, cataratas, aguas termales y orquídeas. Campamento en Sawayaco.'),(133,34,4,'Sawayaco – Llactapata – Aguas Calientes','Ascenso a Llactapata con vistas a Machu Picchu. Descenso a la hidroeléctrica y tren hacia Aguas Calientes. Noche en hotel.'),(134,34,5,'Machu Picchu – Cusco','Visita guiada de 2h30 a Machu Picchu: Plaza Principal, Intihuatana, Templo del Cóndor, Tres Ventanas. Tiempo libre para explorar o subir a Huayna Picchu (opcional). Retorno en tren a Cusco.'),(135,35,1,'Iquitos – Ceiba Tops','Recepción en aeropuerto y traslado al embarcadero. Breve tour por la ciudad y navegación de 40 km por el Amazonas hasta Ceiba Tops. Caminata por bosque primario con el árbol Ceiba. Cena y excursión nocturna para observar fauna. Pernocte en lodge.'),(136,35,2,'Ceiba Tops – Indiana','Paseo en bote para avistar delfines rosados y grises. Por la tarde visita al pueblo ribereño de Indiana, fundado por franciscanos. Posible observación del atardecer en el Amazonas. Pernocte en lodge.'),(137,35,3,'Ceiba Tops – Iquitos','Excursión en bote a un afluente del Amazonas para pesca de pirañas. Almuerzo y retorno a Iquitos. Noche en hotel de ciudad.'),(138,35,4,'Iquitos Out','Desayuno en el hotel. Mañana libre para actividades personales. Traslado al aeropuerto.'),(139,36,1,'Iquitos – Ceiba Tops','Recepción en aeropuerto y traslado al embarcadero. Breve tour por la ciudad y navegación de 40 km por el Amazonas hasta Ceiba Tops. Caminata por bosque primario con el árbol Ceiba. Cena y excursión nocturna para observar fauna.'),(140,36,2,'Ceiba Tops – Delfines & Indiana','Paseo en bote para avistar delfines rosados y grises. Por la tarde visita al pueblo ribereño de Indiana, fundado por franciscanos. Posible observación del atardecer en el Amazonas.'),(141,36,3,'Ceiba Tops – Mariposario & Kayak','Excursión al Mariposario de San Rafael para conocer el ciclo de vida de las mariposas. Por la tarde, paseo en kayak por afluentes del Amazonas.'),(142,36,4,'Ceiba Tops – Iquitos','Excursión en bote y visita adicional al pueblo de Indiana. Retorno a Iquitos y alojamiento en hotel de ciudad.'),(143,36,5,'Iquitos Out','Desayuno en el hotel. Mañana libre para actividades personales. Traslado al aeropuerto.'),(144,37,1,'Iquitos – Curaka Inn','Recepción en aeropuerto u hotel, breve city tour peatonal (Iglesia Matriz, Casa de Fierro, Malecón Maldonado). Navegación por el río Itaya y Amazonas con avistamiento de delfines. Llegada al lodge, almuerzo típico, caminata por la selva y excursión nocturna en canoa. Cena y pernocte.'),(145,37,2,'Curaka Lodge – Fauna y Cultura Ribereña','Avistaje de aves. Visita a moradores ribereños para observar boas, osos perezosos y tortugas. Degustación de caña de azúcar. Almuerzo típico (patarashca). Por la tarde visita al pueblo ribereño Gallito y puesta de sol. Cena y pernocte.'),(146,37,3,'Curaka Lodge – Iquitos','Pesca en el Amazonas (pirañas, pez gato). Observación de la Victoria Regia. Almuerzo típico de pescado dorado. Retorno a Iquitos con visita a la comunidad nativa Bora Bora (costumbres, dialecto, vestimenta, danzas y artesanías). Noche en hotel de ciudad.'),(147,37,4,'Iquitos Out','Desayuno en el hotel. Día libre para actividades personales. Traslado al aeropuerto.'),(148,38,1,'Iquitos – Heliconia Lodge','Traslado en bote por el Amazonas y Nanay, con parada en la Isla de Monos o Fundo Pedrito. Bienvenida en el lodge y caminata por la reserva Yanamono para conocer plantas medicinales y árboles gigantes. Paseo nocturno en bote por afluentes del Amazonas.'),(149,38,2,'Heliconia Lodge – Comunidad Yaguas','Avistamiento de aves al amanecer. Visita a la comunidad Yaguas para participar en sus tradiciones y uso de la \"pucuna\". Almuerzo típico y pesca artesanal de pirañas. Observación de delfines rosados. Caminata nocturna por la selva.'),(150,38,3,'Heliconia Lodge – Iquitos','Excursión a lagos y pantanos para observar la Victoria Regia, el lirio acuático más grande del mundo. Almuerzo en el lodge y retorno a Iquitos. Noche en hotel de ciudad.'),(151,38,4,'Iquitos Out','Desayuno en el hotel. Mañana libre para actividades personales. Traslado al aeropuerto.'),(152,39,1,'Iquitos – Heliconia Lodge','Traslado en bote por los ríos Amazonas y Nanay, con parada en la Isla de Monos o Fundo Pedrito. Bienvenida en el lodge y caminata guiada por la reserva Yanamono para conocer flora y árboles gigantes. Paseo nocturno en bote por afluentes del Amazonas.'),(153,39,2,'Heliconia Lodge – Comunidad Yaguas','Avistamiento de aves al amanecer. Visita a la comunidad Yaguas para participar en sus costumbres y aprender el uso de la \"pucuna\". Almuerzo típico. Por la tarde, pesca artesanal de pirañas y avistamiento de delfines rosados. Caminata nocturna por la selva.'),(154,39,3,'Heliconia Lodge – Victoria Regia & Trapiche Amazónico','Excursión en bote para observar la Victoria Regia, el lirio acuático más grande del mundo. Almuerzo en el lodge y descanso. Por la tarde, visita al Trapiche Amazónico para conocer el proceso de la caña de azúcar y degustar licores regionales.'),(155,39,4,'Heliconia Lodge – Iquitos','Tour de canotaje en el Amazonas y quebradas cercanas para contemplar la fauna en silencio. Almuerzo de despedida en el lodge. Retorno a Iquitos y alojamiento en hotel de ciudad.'),(156,39,5,'Iquitos Out','Desayuno en el hotel. Mañana libre para actividades personales. Traslado al aeropuerto.'),(157,40,1,'Cusco – Bosque de Nubes – San Pedro','Salida temprano desde Cusco. Visita a las tumbas pre-incas de Ninamarca y al pueblo colonial de Paucartambo. Ascenso al abra de Acjanacu (3,850 m.s.n.m.) y descenso al Bosque de Nubes, hábitat del Gallito de las Rocas. Almuerzo en ruta y pernocte en albergue Orquídeas de San Pedro.'),(158,40,2,'San Pedro – Pilcopata – Atalaya – Erika Lodge','Observación del Gallito de las Rocas. Traslado en bus hasta Pilcopata y luego al puerto de Atalaya (700 m.s.n.m.). Navegación por el río Alto Madre de Dios hasta la Reserva Privada Erika. Caminata por trochas de transición entre selva alta y baja. Pernocte en Erika Lodge. (Opcional gratuito: canotaje en ríos Koshñipata y/o Alto Madre de Dios)'),(159,40,3,'Erika Lodge – Machuwasi','Exploración de hábitats diversos. Caminata hacia la laguna Machuwasi para observación de aves como tucanetas, garza real y carpintero crestirojo. (Opcional gratuito: canopy tour sobre la copa de los árboles con arneses y rappel de 30 m)'),(160,40,4,'Erika Lodge – Collpa de Loros – Cusco','Visita a la Collpa de loros para observar especies como el loro cabeza azul y guacamayos. Retorno en bote a Atalaya y viaje en bus hacia Cusco. Almuerzo en ruta y llegada por la noche.'),(161,41,1,'Cusco – Bosque de Nubes – San Pedro','Salida temprano desde Cusco. Visita a las tumbas pre-incas de Ninamarca y al pueblo colonial de Paucartambo. Ascenso al abra de Acjanacu (3,850 m.s.n.m.) y descenso al Bosque de Nubes. Pernocte en albergue Orquídeas de San Pedro.'),(162,41,2,'San Pedro – Pilcopata – Atalaya – Erika Lodge','Observación del Gallito de las Rocas. Traslado a Pilcopata y navegación por el río Alto Madre de Dios hasta la Reserva Privada Erika. Caminata por trochas de transición entre selva alta y baja. (Opcional gratuito: canotaje en ríos Koshñipata y/o Alto Madre de Dios)'),(163,41,3,'Collpa de Pericos – Zona Reservada – Cocha Salvador','Registro en Puesto de Vigilancia Limonal y navegación hacia la Zona Reservada. Instalación en campamento Sajino Safari. Exploración de la selva virgen.'),(164,41,4,'Cocha Salvador','Caminata matutina y recorrido en catamarán para observar Nutria Gigante, Caimán Negro, Hoatzin y monos.'),(165,41,5,'Cocha Otorongo – Observación de fauna','Caminata por bosque primario y observación desde torre de 15 m. Retorno a Cocha Salvador y observación nocturna de caimanes.'),(166,41,6,'Cocha Salvador – Boca Manu','Caminata y navegación hacia Boca Manu, con posibilidad de caminata nocturna.'),(167,41,7,'Boca Manu – Erika Lodge / Playa Amazónica','Navegación por el río Madre de Dios. Pernocte en Erika Lodge o campamento en playa amazónica.'),(168,41,8,'Retorno a Cusco','Navegación hacia Atalaya y viaje en bus a Cusco. Llegada por la noche o al día siguiente temprano.'),(169,42,1,'Bienvenida – Cocha Caimán','Recepción en aeropuerto y breve city tour por Puerto Maldonado. Navegación por el río Madre de Dios con avistamiento de fauna (ronsocos, caimanes, tortugas, aves). Llegada al lodge, almuerzo y caminata hacia la Cocha Caimán para observar caimanes negros y blancos. Atardecer amazónico y cena en el lodge.'),(170,42,2,'Lago Apu Victor – Isla de los Monos','Amanecer con cantos de aves y monos aulladores. Caminata por trochas amazónicas hasta el Lago Apu Victor y ascenso al Mirador Amazónico para observar aves, caimanes, tortugas y, con suerte, nutrias gigantes. Almuerzo en lodge. Por la tarde visita a la Isla de los Monos para observar maquisapa, capuchino, leoncillo y fraile. Cena en lodge.'),(171,42,3,'Retorno – Puerto Maldonado – Lima','Desayuno en lodge. Retorno a Puerto Maldonado y traslado al aeropuerto para vuelo de regreso.'),(172,43,1,'Bienvenida – Cocha Caimán','Recepción en aeropuerto y city tour por Puerto Maldonado. Navegación por el río Madre de Dios con avistamiento de fauna (ronsocos, caimanes, tortugas, aves). Llegada al lodge, almuerzo y caminata hacia la Cocha Caimán para observar caimanes negros y blancos. Cena y descanso en lodge.'),(173,43,2,'Lago Apu Victor – Isla de los Monos','Caminata por el bosque amazónico hasta el Lago Apu Victor y ascenso al Mirador Amazónico para observar aves, caimanes y nutrias gigantes. Almuerzo en lodge. Por la tarde visita a la Isla de los Monos para observar maquisapa, capuchino y fraile. Cena en lodge.'),(174,43,3,'Cocha Perdida – Jardín Botánico / Piscina Amazónica','Caminata por la selva virgen hasta la Cocha Perdida, ecosistema único de la reserva. Observación de nutrias, caimanes, aves multicolores y, con suerte, jaguar o sachavaca. Paseo en canoa y visita opcional al Jardín Botánico o tiempo libre en la piscina. Cena en lodge.'),(175,43,4,'Retorno – Puerto Maldonado – Lima','Desayuno en lodge. Retorno a Puerto Maldonado y traslado al aeropuerto para vuelo de regreso.'),(176,44,1,'Bienvenida – Cocha Caimán','Recepción en aeropuerto y city tour por Puerto Maldonado. Navegación en canoa motorizada por el río Madre de Dios con avistamiento de fauna (ronsocos, caimanes, tortugas, aves). Llegada al lodge, almuerzo y caminata hacia la Cocha Caimán para observar caimanes negros y blancos. Cena y descanso en lodge.'),(177,44,2,'Lago Apu Victor – Isla de los Monos','Caminata por el bosque amazónico hasta el Lago Apu Victor y ascenso al Mirador Amazónico para observar aves, caimanes y nutrias gigantes. Almuerzo en lodge. Por la tarde visita a la Isla de los Monos para observar maquisapa, capuchino y fraile. Cena en lodge.'),(178,44,3,'Cocha Perdida – Jardín Botánico / Piscina Amazónica','Caminata por la selva virgen hasta la Cocha Perdida, ecosistema único de la reserva. Observación de nutrias, caimanes, aves multicolores y, con suerte, jaguar o sachavaca. Paseo en canoa y visita opcional al Jardín Botánico o tiempo libre en la piscina. Cena en lodge.'),(179,44,4,'Retorno – Puerto Maldonado – Lima','Desayuno en lodge. Retorno a Puerto Maldonado y traslado al aeropuerto para vuelo de regreso.'),(180,45,1,'Catarata Santa Carmen – Parque Nacional','Recepción en terminal y traslado al hotel. Excursión a la Catarata Santa Carmen y Balneario de las Cuevas de las Pavas. Almuerzo típico. Visita al Parque Nacional de Tingo María: Cueva de las Lechuzas, Mirador Jacintillo, aguas sulfurosas y serpentario Animals Paradise. Retorno y pernocte.'),(181,45,2,'Escalada Catarata de las Ninfas','Desayuno. Caminata y escalada por un circuito de 12 cataratas hasta llegar a la Catarata de las Ninfas. Almuerzo típico y tarde libre. Pernocte.'),(182,45,3,'Zoocriadero UNAS – Laguna Los Milagros – Retorno','Desayuno. Visita al Zoocriadero de la UNAS y caminata hacia la Laguna Los Milagros. Paseo en bote y natación. Almuerzo típico y tarde libre. Traslado al terminal y retorno a ciudad de origen.'),(183,46,1,'Catarata Santa Carmen – Parque Nacional','Recepción en terminal y traslado al hotel. Excursión a la Catarata Santa Carmen con degustación de raspadilla ecológica. Visita al Balneario Cuevas de las Pavas, Parque Nacional de Tingo María, Mirador Jacintillo, aguas sulfurosas, Cueva de las Lechuzas y serpentario Animals Paradise. Retorno y pernocte.'),(184,46,2,'Boquerón del Padre Abad – Aguaytía','Desayuno. Excursión al Boquerón del Padre Abad, Cordillera Azul, Catarata Velo de la Novia y Ducha del Diablo. Almuerzo típico en Aguaytía. Caminata por el puente más largo del país y visita al túnel del boquerón. Retorno y pernocte en Tingo María.'),(185,46,3,'Zoocriadero UNAS – Laguna Los Milagros','Visita al Zoocriadero de la UNAS y caminata hacia la Laguna Los Milagros. Paseo en bote y natación. Opcional canopy. Almuerzo típico y retorno a Tingo María. Pernocte.'),(186,46,4,'Escalada Catarata de las Ninfas – Retorno','Desayuno. Caminata y escalada por un circuito de 12 cataratas hasta llegar a la Catarata de las Ninfas. Almuerzo típico y retorno a ciudad de origen.'),(187,47,1,'Catarata Santa Carmen – Parque Nacional','Recepción en terminal y traslado al hotel. Excursión a la Catarata Santa Carmen con degustación de raspadilla ecológica. Visita al Balneario Cuevas de las Pavas, Parque Nacional de Tingo María, Mirador Jacintillo, aguas sulfurosas, Cueva de las Lechuzas y serpentario Animals Paradise. Retorno y pernocte.'),(188,47,2,'Escalada Catarata de las Ninfas','Desayuno. Caminata y escalada por un circuito de 12 cataratas hasta llegar a la Catarata de las Ninfas. Almuerzo típico. Retorno a la ciudad y opción de City by Night. Pernocte.'),(189,47,3,'Zoocriadero UNAS – Laguna Los Milagros','Desayuno. Visita al Zoocriadero de la UNAS y caminata hacia la Laguna Los Milagros. Paseo en bote y natación. Opcional canopy. Almuerzo típico y retorno a Tingo María. Pernocte.'),(190,47,4,'Boquerón del Padre Abad – Aguaytía','Desayuno. Excursión al Boquerón del Padre Abad, Cordillera Azul, Catarata Velo de la Novia y Ducha del Diablo. Almuerzo típico en Aguaytía. Caminata por el puente más largo del país y visita al túnel del boquerón. Retorno a Tingo María. (Disponible de mayo a octubre)'),(191,47,5,'Catarata Gloriapata – Poza del Amor – Retorno','Desayuno. Excursión a la Catarata Gloriapata y Poza del Amor en Santa Rosa de Quezada. Almuerzo típico. Tarde libre para compras. Traslado al terminal y retorno a ciudad de origen.'),(192,1,1,'Llegada a Cusco','Recepción en aeropuerto y traslado al hotel, tiempo libre para aclimatación.'),(193,1,2,'Tour arqueológico','Visita a Sacsayhuamán, Qenqo y transporte a Aguas Calientes.'),(194,1,3,'Machu Picchu','Visita guiada a Machu Picchu y tiempo libre para explorar.'),(195,1,4,'Regreso a casa','Desayuno y traslado al aeropuerto de Cusco.'),(196,2,1,'Cusco histórico','Recorrido por la Plaza de Armas y museos inolvidables.'),(197,2,2,'Valle Sagrado','Visita a Pisac y Ollantaytambo con mercado tradicional.'),(198,2,3,'Maras y Moray','Exploración de las salineras y terrazas agrícolas.'),(199,2,4,'Tiempo libre','Opcional: clase de cocina o visita a artistas locales.'),(200,2,5,'Salida','Traslado al aeropuerto de Cusco.'),(201,3,1,'Llegada a Lima','Recepción y tour por Miraflores.'),(202,3,2,'Barranco y sabores','Recorrido por el barrio bohemio y degustación local.'),(203,3,3,'Rumbo a casa','Desayuno y traslado al aeropuerto.'),(204,4,1,'Iquitos y Amazonía','Llegada a Iquitos y traslado al lodge.'),(205,4,2,'Río Amazonas','Paseo en bote y avistamiento de fauna.'),(206,4,3,'Aldea nativa','Visita cultural a una comunidad local.'),(207,4,4,'Senderismo','Caminata por la selva y observación de aves.'),(208,4,5,'Descanso','Tiempo libre en el lodge.'),(209,4,6,'Regreso','Traslado al aeropuerto de Iquitos.');
