LOCK TABLES `testimonios` WRITE;
/*!40000 ALTER TABLE `testimonios` DISABLE KEYS */;
INSERT INTO `testimonios` VALUES (1,'Ana García','Profesora, Lima',5,'¡Experiencia increíble! El paquete de Machu Picchu superó todas mis expectativas. El guía fue excepcional y la organización perfecta.','https://randomuser.me/api/portraits/women/1.jpg'),(2,'Carlos Mendoza','Ingeniero, Arequipa',5,'La Amazonía fue una aventura de otro mundo. Ver caimanes y nutrias gigantes en su hábitat natural fue emocionante. ¡100% recomendado!','https://randomuser.me/api/portraits/men/2.jpg'),(3,'María Flores','Empresaria, Cusco',4,'El Lago Titicaca y sus islas fueron una experiencia cultural única. Convivir con la familia local en Amantaní cambió mi perspectiva de vida.','https://randomuser.me/api/portraits/women/3.jpg'),(4,'Roberto Silva','Médico, Trujillo',5,'El paquete de Lima fue de primer nivel. Los restaurantes seleccionados son de clase mundial. La ciudad me sorprendió gratamente.','https://randomuser.me/api/portraits/men/4.jpg'),(5,'Lucía Torres','Diseñadora, Piura',5,'El Cañón del Colca es espectacular. Ver los cóndores volar al amanecer fue un momento que jamás olvidaré. Excelente organización.','https://randomuser.me/api/portraits/women/5.jpg'),(6,'Miguel Quispe','Periodista, Cusco',4,'Las Líneas de Nazca desde el aire son impresionantes. El vuelo en avioneta valió cada sol. Una experiencia mística e inolvidable.','https://randomuser.me/api/portraits/men/6.jpg'),(7,'María Pérez','Viajeras felices',5,'Excelente atención y un itinerario muy bien organizado. ¡Repetiría seguro!','https://images.unsplash.com/photo-1502685104226-ee32379fefbe?w=200&q=80'),(8,'Juan Díaz','Aventurero',5,'Machu Picchu fue impresionante y el guía explicó todo con claridad.','https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?w=200&q=80'),(9,'Ana Torres','Familia',4,'La experiencia en Lima fue muy completa y la comida deliciosa.','https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=200&q=80'),(10,'Ricardo Gómez','Naturalista',5,'La expedición en la selva superó mis expectativas. Muy recomendable.','https://images.unsplash.com/photo-1517841905240-472988babdf9?w=200&q=80');
/*!40000 ALTER TABLE `testimonios` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `usuarios`
